kernels.wgsl:
@group(0) @binding(0) var<storage, read> b0: array<f32>;
@group(0) @binding(1) var<storage, read> b1: array<f32>;
@group(0) @binding(2) var<storage, read> b2: array<f32>;
@group(0) @binding(3) var<storage, read> b3: array<f32>;
@group(0) @binding(4) var<storage, read_write> bout: array<f32>;
var<workgroup> sA0: array<f32, 1024>;
var<workgroup> sB0: array<f32, 128>;

@compute @workgroup_size(1024)
fn main(@builtin(local_invocation_index) lid: u32, @builtin(workgroup_id) wid: vec3<u32>, @builtin(num_workgroups) nwg: vec3<u32>) {
    let tid: i32 = i32(lid);
    let bid: i32 = i32(wid.x) + i32(wid.y) * i32(nwg.x);
    if (bid >= 96i) { return; }
    var v_acc_0_0: f32 = 0.0;
    var v_acc_0_1: f32 = 0.0;
    var v_tv: f32 = 0.0;
    var v_g0: f32 = 0.0;
    var v_g1: f32 = 0.0;
    var v_a0_0: f32 = 0.0;
    var v_b0_0: f32 = 0.0;
    var v_b0_1: f32 = 0.0;
    var v_v1_0_0: f32 = 0.0;
    var v_v2_0_0: f32 = 0.0;
    var v_v3_0_0: f32 = 0.0;
    var v_v1_0_1: f32 = 0.0;
    var v_v2_0_1: f32 = 0.0;
    var v_v3_0_1: f32 = 0.0;
    var v_in0_0_0: f32 = 0.0;
    var v_v0_0_0: f32 = 0.0;
    var v_v4_0_0: f32 = 0.0;
    var v_v5_0_0: f32 = 0.0;
    var v_in3_0_0: f32 = 0.0;
    var v_v6_0_0: f32 = 0.0;
    var v_in0_0_1: f32 = 0.0;
    var v_v0_0_1: f32 = 0.0;
    var v_v4_0_1: f32 = 0.0;
    var v_v5_0_1: f32 = 0.0;
    var v_in3_0_1: f32 = 0.0;
    var v_v6_0_1: f32 = 0.0;
    var n_bz: i32 = 0i;
    var n_bm: i32 = 0i;
    var n_bn: i32 = 0i;
    var n_ty: i32 = 0i;
    var n_tx: i32 = 0i;
    var n_rr: i32 = 0i;
    var n_kq: i32 = 0i;
    n_bz = (bid / 96i);
    n_bm = ((bid / 48i) % 2i);
    n_bn = (bid % 48i);
    n_ty = (tid / 8i);
    n_tx = (tid % 8i);
    v_acc_0_0 = 0.0;
    v_acc_0_1 = 0.0;
    for (var n_k0: i32 = 0i; n_k0 < 196i; n_k0 = n_k0 + 8i) {
        for (var n_la: i32 = tid; n_la < 1024i; n_la = n_la + 1024i) {
            n_rr = (n_la / 8i);
            n_kq = (n_la % 8i);
            v_tv = 0.0;
            if ((((128i * n_bm) + n_rr) < 196i) && ((n_k0 + n_kq) < 196i)) {
                v_g0 = b2[((((25088i * n_bm) + n_k0) + n_kq) + (196i * n_rr))];
                v_tv = v_g0;
            }
            sA0[(n_kq + (8i * n_rr))] = v_tv;
        }
        for (var n_lb: i32 = tid; n_lb < 128i; n_lb = n_lb + 1024i) {
            n_rr = (n_lb / 8i);
            n_kq = (n_lb % 8i);
            v_tv = 0.0;
            if ((((16i * n_bn) + n_rr) < 768i) && ((n_k0 + n_kq) < 196i)) {
                v_g1 = b3[((((3136i * n_bn) + n_k0) + n_kq) + (196i * n_rr))];
                v_tv = v_g1;
            }
            sB0[((16i * n_kq) + n_rr)] = v_tv;
        }
        workgroupBarrier();
        for (var n_kk: i32 = 0i; n_kk < 8i; n_kk = n_kk + 1i) {
            if ((n_k0 + n_kk) < 196i) {
                v_a0_0 = sA0[(n_kk + (8i * n_ty))];
                v_b0_0 = sB0[((16i * n_kk) + (2i * n_tx))];
                v_b0_1 = sB0[(((16i * n_kk) + (2i * n_tx)) + 1i)];
                v_v1_0_0 = v_a0_0;
                v_v2_0_0 = v_b0_0;
                v_v3_0_0 = (v_v1_0_0 * v_v2_0_0);
                v_acc_0_0 = (v_acc_0_0 + v_v3_0_0);
                v_v1_0_1 = v_a0_0;
                v_v2_0_1 = v_b0_1;
                v_v3_0_1 = (v_v1_0_1 * v_v2_0_1);
                v_acc_0_1 = (v_acc_0_1 + v_v3_0_1);
            }
        }
        workgroupBarrier();
    }
    if ((((128i * n_bm) + n_ty) < 196i) && (((16i * n_bn) + (2i * n_tx)) < 768i)) {
        v_in0_0_0 = b1[((128i * n_bm) + n_ty)];
        v_v0_0_0 = v_in0_0_0;
        v_v4_0_0 = (v_v0_0_0 + v_acc_0_0);
        v_v5_0_0 = v_v4_0_0;
        v_in3_0_0 = b0[((((98304i * n_bm) + (16i * n_bn)) + (2i * n_tx)) + (768i * n_ty))];
        v_v6_0_0 = (v_v5_0_0 * v_in3_0_0);
        bout[((((98304i * n_bm) + (16i * n_bn)) + (2i * n_tx)) + (768i * n_ty))] = v_v6_0_0;
    }
    if ((((128i * n_bm) + n_ty) < 196i) && ((((16i * n_bn) + (2i * n_tx)) + 1i) < 768i)) {
        v_in0_0_1 = b1[((128i * n_bm) + n_ty)];
        v_v0_0_1 = v_in0_0_1;
        v_v4_0_1 = (v_v0_0_1 + v_acc_0_1);
        v_v5_0_1 = v_v4_0_1;
        v_in3_0_1 = b0[(((((98304i * n_bm) + (16i * n_bn)) + (2i * n_tx)) + (768i * n_ty)) + 1i)];
        v_v6_0_1 = (v_v5_0_1 * v_in3_0_1);
        bout[(((((98304i * n_bm) + (16i * n_bn)) + (2i * n_tx)) + (768i * n_ty)) + 1i)] = v_v6_0_1;
    }
}
